// Package chainledger implements the on-chain data governance core.
package chainledger

import "sort"

// Dataset is one ingestible on-chain data source with a declared schema version.
type Dataset struct {
	Name          string
	SchemaVersion int
	Rows          int
	Upstreams     []string
}

// Lineage records where a dataset came from, so every derived table can be traced.
type Lineage struct {
	Dataset  string
	Parents  []string
	Children []string
}

// Register links a dataset into the lineage graph and rejects cycles.
//
// Re-registering an existing dataset replaces its direct upstreams with parents
// (de-duplicated, first occurrence wins, list order preserved) while keeping its
// existing direct downstreams. Reverse edges stay consistent: upstreams removed
// from the list drop the dataset from their children, newly added upstreams gain
// it at the end of their children, and retained upstreams keep exactly one entry
// in its original position.
//
// The whole request is validated before the graph is touched, so a rejected
// registration leaves every node, edge and ordering untouched. The parents slice
// is copied: mutating it after Register returns does not affect the graph.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if dataset.Name == "" {
		return errInvalid("dataset name is required")
	}

	// Validate up front, walking the request in input order so the first problem
	// encountered is the one reported. No graph mutation happens in this loop.
	upstreams := make([]string, 0, len(parents))
	known := map[string]bool{}
	// All cycle checks in this one request share a single memoized walk over the
	// graph as it stands now: probe records whether each visited node can reach
	// dataset.Name through existing parent edges. Candidate upstreams that come
	// from the same source or merge repeatedly (diamonds) then traverse the
	// shared lineage once instead of re-walking it per candidate. The recorded
	// conclusion is a property of the current graph, so it is never reused
	// across registrations.
	probe := newAncestorProbe(graph, dataset.Name)
	for _, parent := range parents {
		if parent == dataset.Name {
			return errInvalid("dataset " + dataset.Name + " cannot be its own parent")
		}
		if _, ok := graph[parent]; !ok {
			return errInvalid("unknown parent " + parent)
		}
		// A new edge dataset -> parent closes a cycle exactly when parent can
		// already reach dataset through existing parent edges. This covers
		// transitive paths of any depth, not only direct mutual references;
		// shared ancestors and diamond merges read as the benign merges they are
		// unless a branch genuinely leads back to dataset.
		if probe.canReach(parent) {
			return errInvalid("cycle through " + parent + " for dataset " + dataset.Name)
		}
		if !known[parent] {
			known[parent] = true
			upstreams = append(upstreams, parent)
		}
	}

	entry, existed := graph[dataset.Name]
	if !existed {
		entry = &Lineage{Dataset: dataset.Name}
	}

	// Remove reverse edges from upstreams the dataset no longer declares.
	for _, old := range entry.Parents {
		if known[old] {
			continue
		}
		if p, ok := graph[old]; ok {
			p.Children = removeChild(p.Children, dataset.Name)
		}
	}

	// Mirror every declared upstream exactly once. An existing edge keeps its
	// position; a missing edge is appended after the current children.
	for _, parent := range upstreams {
		graph[parent].Children = addChildOnce(graph[parent].Children, dataset.Name)
	}

	entry.Parents = upstreams
	if !existed {
		graph[dataset.Name] = entry
	}
	return nil
}

// Rename changes the registered name of the dataset oldName to newName while
// keeping the dataset's exact position in the lineage graph: the node keeps
// its own direct upstream and downstream lists untouched, and every neighbor
// that referenced oldName now references newName in the same list position.
// No edge is added, removed, merged or reordered, and the total number of
// datasets in the graph is unchanged. Roots, leaves and intermediate datasets
// can all be renamed.
//
// The request is validated before the graph is touched, so a rejected rename
// leaves every node, edge and list order untouched. Names match by exact
// registered value (case-sensitive). An empty old or new name is rejected as
// a missing name; an oldName absent from the graph is rejected with an error
// naming it; a newName already registered to a different dataset is rejected
// with an error naming it. Renaming a dataset to its own current name is a
// successful no-op.
func Rename(graph map[string]*Lineage, oldName, newName string) error {
	if oldName == "" {
		return errInvalid("dataset name is required")
	}
	if newName == "" {
		return errInvalid("new dataset name is required")
	}
	entry, ok := graph[oldName]
	if !ok {
		return errInvalid("dataset not found: " + oldName)
	}
	if oldName == newName {
		return nil
	}
	if _, taken := graph[newName]; taken {
		return errInvalid("dataset name already in use: " + newName)
	}

	delete(graph, oldName)
	entry.Dataset = newName
	graph[newName] = entry

	// Rewire the reverse references in place: the renamed node keeps its slot
	// in every neighbor's list, so each neighbor's ordering is preserved.
	for _, parent := range entry.Parents {
		children := graph[parent].Children
		for i, child := range children {
			if child == oldName {
				children[i] = newName
			}
		}
	}
	for _, child := range entry.Children {
		parents := graph[child].Parents
		for i, parent := range parents {
			if parent == oldName {
				parents[i] = newName
			}
		}
	}
	return nil
}

// Unregister removes a dataset registration from the lineage graph.
//
// Only a leaf dataset can be removed: a dataset with any direct downstream
// (a dataset still derived from it) is kept, regardless of how many upstreams
// it itself has. A removable dataset may still have direct upstreams; every
// one of them drops the dataset from its downstream list, in that list's
// original position, and the upstreams themselves and their other
// downstreams are untouched. A dataset with neither upstreams nor
// downstreams can also be removed. On success the name is gone from the
// graph: Impacts and Upstreams treat it as unregistered, and no empty node
// remains behind.
//
// The request is fully validated before the graph is touched, so a rejected
// removal leaves every node, edge and list order exactly as it was — no
// upstream can end up detached while the dataset stays. An empty name is
// rejected as a missing name; a non-empty name absent from the graph (also
// against an empty or nil graph) is rejected with an error naming it; a
// dataset that still has direct downstreams is rejected with an error that
// names it and states the remaining downstream. Names match by exact
// registered value (case-sensitive).
func Unregister(graph map[string]*Lineage, name string) error {
	if name == "" {
		return errInvalid("dataset name is required")
	}
	entry, ok := graph[name]
	if !ok {
		return errInvalid("dataset not found: " + name)
	}
	if len(entry.Children) > 0 {
		return errInvalid("dataset " + name + " cannot be unregistered while it still has direct downstreams")
	}

	// The dataset is a leaf, so its only edges point at its direct upstreams.
	// Drop the matching reverse edge from each one, preserving the remaining
	// order, then remove the node itself. The checks above guarantee nothing
	// points back at it, so the graph stays fully consistent.
	for _, parent := range entry.Parents {
		if p, ok := graph[parent]; ok {
			p.Children = removeChild(p.Children, name)
		}
	}
	delete(graph, name)
	return nil
}

// ancestorProbe answers "can node reach target by following parent edges?" for
// many starting nodes against one fixed, read-only snapshot of the graph, i.e.
// whether target is among each node's direct or transitive upstreams. Each node
// in the shared ancestry is resolved at most once, so candidate parents that
// descend from a common source or merge along the way reuse the same findings
// instead of each paying for a complete traversal.
type ancestorProbe struct {
	graph  map[string]*Lineage
	target string
	// resolved caches the conclusion for every fully explored node; visiting
	// marks nodes mid-resolution. Register never accepts cycles, but visiting
	// doubles as cycle protection regardless.
	resolved map[string]bool
	visiting map[string]bool
}

func newAncestorProbe(graph map[string]*Lineage, target string) *ancestorProbe {
	return &ancestorProbe{
		graph:    graph,
		target:   target,
		resolved: map[string]bool{},
		visiting: map[string]bool{},
	}
}

func (p *ancestorProbe) canReach(node string) bool {
	if node == p.target {
		return true
	}
	if hit, ok := p.resolved[node]; ok {
		return hit
	}
	if p.visiting[node] {
		return false
	}
	p.visiting[node] = true

	found := false
	if entry, ok := p.graph[node]; ok {
		for _, parent := range entry.Parents {
			if p.canReach(parent) {
				found = true
				break
			}
		}
	}
	delete(p.visiting, node)
	p.resolved[node] = found
	return found
}

// removeChild drops every occurrence of child from children, preserving the
// relative order of the remaining entries.
func removeChild(children []string, child string) []string {
	out := children[:0]
	for _, c := range children {
		if c != child {
			out = append(out, c)
		}
	}
	return out
}

// addChildOnce ensures child appears exactly once in children. An existing entry
// keeps its position (duplicate later entries are dropped); otherwise child is
// appended at the end.
func addChildOnce(children []string, child string) []string {
	out := children[:0]
	present := false
	for _, c := range children {
		if c == child {
			if present {
				continue
			}
			present = true
		}
		out = append(out, c)
	}
	if !present {
		out = append(out, child)
	}
	return out
}

// Impact names one dataset directly or indirectly downstream of an impact
// query's origin. Distance is the number of lineage edges on the shortest path
// from the origin to this dataset (a direct downstream has distance 1), and
// Path is that shortest path written from the origin to the dataset, one name
// per hop.
type Impact struct {
	Dataset  string
	Distance int
	Path     []string
}

// Impacts returns every dataset directly or indirectly downstream of origin,
// i.e. every dataset reachable from origin by following child edges. The origin
// itself is never listed, and datasets with no such connection never appear.
//
// Impacts is exactly the no-cutoff form of ImpactsWithCutoffs: it behaves as if
// every registered dataset were allowed to propagate. Distance, the
// tie-broken explanation path, result ordering, read-only graph access and
// error handling all follow the single shared lineage-query rule set
// implemented by traceLineage; only the direction is specific to Impacts:
// child edges outward, with paths written from the origin. An empty origin is
// rejected as a missing name; an origin absent from the graph (including an
// empty or nil graph) is rejected with an error naming it and no partial
// results.
func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
	return ImpactsWithCutoffs(graph, origin, nil)
}

// ImpactsWithCutoffs returns every dataset downstream of origin that is still
// reachable when propagation is stopped at the registered datasets named in
// cutoffs. It answers "how far does a change to origin spread if the change is
// not allowed to travel past these datasets?"
//
// A cutoff dataset that is itself reachable from origin IS included in the
// results at its own shortest distance, but the traversal never continues to
// its downstreams through it. A dataset lying past a cutoff is still listed as
// long as some other route from origin reaches it without passing any cutoff;
// only when every route runs through a cutoff does the dataset (and whatever is
// reachable through it alone) leave the result. Distances and explanation
// paths are computed solely over routes that pass no cutoff — they never reuse
// a path that the full query could take once that path has been truncated —
// with the same two-level choice as Impacts: fewest edges first, and among
// equal-length routes the lexicographically smallest full path, compared name
// by name from the origin in Go string order. Each dataset appears at most
// once, and records stay ordered by distance ascending and then by dataset
// name.
//
// With an empty (or nil) cutoff list the result is identical to Impacts. A
// repeated cutoff name acts only once; a cutoff that is registered but not
// reachable from origin changes nothing; a cutoff named after the origin
// itself is a successful query that returns a non-nil empty list, and the
// origin is still never listed as affected. Names match by exact registered
// value (case-sensitive).
//
// Like Impacts, the query is read-only: it changes no node, edge or stored
// list order, and every returned Path is an independent copy. An empty origin
// is rejected as a missing name; an origin absent from the graph (including an
// empty or nil graph) is rejected with an error naming it and nil results.
// The whole request fails (with nil results) when the cutoff list names an
// empty dataset (cutoff dataset name is required) or an unregistered one; the
// error names the offending dataset, e.g. "cutoff dataset not found: ghost".
// The origin is validated first, and cutoff problems otherwise surface in the
// cutoff list's input order.
func ImpactsWithCutoffs(graph map[string]*Lineage, origin string, cutoffs []string) ([]Impact, error) {
	hits, err := traceLineage(graph, origin, dirDownstream, cutoffs)
	if err != nil {
		return nil, err
	}
	impacts := make([]Impact, len(hits))
	for i, hit := range hits {
		impacts[i] = Impact{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
	}
	return impacts, nil
}

// Upstream names one dataset directly or indirectly upstream of a provenance
// query's target. Distance is the number of lineage edges on the shortest path
// from this upstream to the target (a direct upstream has distance 1), and
// Path is that shortest path written along the actual derivation direction,
// from this upstream to the queried dataset, one name per hop.
type Upstream struct {
	Dataset  string
	Distance int
	Path     []string
}

// Upstreams returns every dataset directly or indirectly upstream of target,
// i.e. every dataset reachable from target by following parent edges. The
// target itself is never listed, its downstreams never appear, and datasets
// with no such connection never appear.
//
// Distance, the tie-broken explanation path, result ordering, read-only graph
// access and error handling all follow the single shared lineage-query rule
// set implemented by traceLineage; only the direction is specific to
// Upstreams: parent edges inward, with paths written from each source toward
// the target. An empty target is rejected as a missing name; a target absent
// from the graph (including an empty or nil graph) is rejected with an error
// naming it and no partial results.
func Upstreams(graph map[string]*Lineage, target string) ([]Upstream, error) {
	hits, err := traceLineage(graph, target, dirUpstream, nil)
	if err != nil {
		return nil, err
	}
	upstreams := make([]Upstream, len(hits))
	for i, hit := range hits {
		upstreams[i] = Upstream{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
	}
	return upstreams, nil
}

// queryDirection carries the only way the two lineage queries differ: which
// edges to walk and from which end an explanation path is written.
type queryDirection int

const (
	// dirDownstream follows child edges away from the query's origin and grows
	// explanation paths at the far end (origin -> ... -> dataset).
	dirDownstream queryDirection = iota
	// dirUpstream follows parent edges away from the query's target and grows
	// explanation paths at the near end (source -> ... -> target).
	dirUpstream
)

// neighbors lists the datasets one edge beyond node in the query direction.
func (d queryDirection) neighbors(node *Lineage) []string {
	if d == dirDownstream {
		return node.Children
	}
	return node.Parents
}

// extendPath grows a committed shortest path by one hop, placing the new hop
// where the explanation direction requires: a downstream hop is appended
// (origin -> node -> hop), an upstream hop is prepended (hop -> node ->
// target). The result always gets a fresh backing array, so candidates never
// alias each other, committed paths, or slices stored in the graph.
func (d queryDirection) extendPath(path []string, hop string) []string {
	extended := make([]string, len(path)+1)
	if d == dirDownstream {
		copy(extended, path)
		extended[len(extended)-1] = hop
		return extended
	}
	extended[0] = hop
	copy(extended[1:], path)
	return extended
}

// lineageHit is one direction-neutral query result: a reached dataset besides
// the query's own node, its shortest edge distance, and the lexicographically
// smallest shortest explanation path held in an independent slice.
type lineageHit struct {
	name     string
	distance int
	path     []string
}

// traceLineage runs the one query rule set shared by Impacts and Upstreams and
// returns every dataset reachable from start besides start itself. When
// cutoffs is non-empty, a reachable cutoff node is still returned but its
// neighbors are never expanded, so paths that would pass through it disappear;
// a nil cutoffs list means propagation is unrestricted.
//
// The traversal is a BFS that commits a whole distance level at once, so a node
// reached through several branches within the same level keeps exactly one
// candidate before the level commits. The rules shared by both directions are:
//
//   - Distance is the minimum number of lineage edges; a node committed on an
//     earlier level can never be re-explained at a longer one (Register
//     rejects cycles, so equal-length rediscoveries only happen inside one
//     level's candidate map).
//   - Each dataset appears at most once, however many branches merge into it.
//   - Among equal-length shortest paths, the lexicographically smallest full
//     path wins: names are compared one by one from the path's beginning in Go
//     string order. Downstream paths begin at the query origin and upstream
//     paths at the source, so candidates for one upstream share their first
//     hop and compare directly against the committed tails.
//   - Hits are ordered by distance ascending and then by dataset name, never
//     by registration order or the stored parent/child list order.
//
// With cutoffs set, every distance, candidate path and ordering decision is
// taken over edges that leave no cutoff behind: a committed cutoff stays in
// the result but its frontier is dropped, and a node reached around a cutoff
// is explained by the route that avoided it rather than by any truncated
// route from the unrestricted graph.
//
// Explanation paths are written in the query direction (see extendPath). The
// graph is read only and every returned path is an independent copy. An empty
// start is rejected as a missing name; an unregistered start (also against an
// empty or nil graph) is rejected with an error naming it, with nil results;
// a registered start that reaches nothing returns a non-nil empty slice.
// Cutoffs are validated after start, in input order (duplicates acting once):
// an empty cutoff name is a missing-name error and an unregistered cutoff name
// is an error naming it; either failure yields nil results without touching
// the graph.
func traceLineage(graph map[string]*Lineage, start string, direction queryDirection, cutoffs []string) ([]lineageHit, error) {
	if start == "" {
		return nil, errInvalid("dataset name is required")
	}
	if _, ok := graph[start]; !ok {
		return nil, errInvalid("dataset not found: " + start)
	}

	// Resolve the cutoff set only after the start has been validated, walking
	// the list in input order so the first bad name is the one reported. A name
	// that repeats acts once: validation sees it once and the set holds it once.
	blocked := make(map[string]bool, len(cutoffs))
	for _, cutoff := range cutoffs {
		if cutoff == "" {
			return nil, errInvalid("cutoff dataset name is required")
		}
		if _, ok := graph[cutoff]; !ok {
			return nil, errInvalid("cutoff dataset not found: " + cutoff)
		}
		blocked[cutoff] = true
	}

	distance := map[string]int{start: 0}
	best := map[string][]string{start: {start}}
	frontier := []string{start}
	for level := 0; len(frontier) > 0; level++ {
		nextDistance := level + 1
		candidates := map[string][]string{}
		var next []string
		for _, node := range frontier {
			// A reached cutoff stays a result itself but is a dead end: nothing
			// propagates through it, even though a parallel route may still
			// reach the same downstream independently.
			if blocked[node] {
				continue
			}
			for _, hop := range direction.neighbors(graph[node]) {
				if _, seen := distance[hop]; seen {
					continue // reached on an earlier, strictly shorter level
				}
				candidate := direction.extendPath(best[node], hop)
				if current, ok := candidates[hop]; !ok || lessPath(candidate, current) {
					if !ok {
						next = append(next, hop)
					}
					candidates[hop] = candidate
				}
			}
		}
		for _, hop := range next {
			distance[hop] = nextDistance
			best[hop] = candidates[hop]
		}
		frontier = next
	}

	hits := make([]lineageHit, 0, len(distance)-1)
	for name, d := range distance {
		if name == start {
			continue
		}
		hits = append(hits, lineageHit{
			name:     name,
			distance: d,
			path:     append([]string(nil), best[name]...),
		})
	}
	sort.Slice(hits, func(i, j int) bool {
		if hits[i].distance != hits[j].distance {
			return hits[i].distance < hits[j].distance
		}
		return hits[i].name < hits[j].name
	})
	return hits, nil
}

// lessPath reports whether path a sorts before path b as a name sequence:
// names are compared with Go string order from the start, and an equal prefix
// makes the shorter path smaller.
func lessPath(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

// Roots lists datasets with no parents, in stable order.
func Roots(graph map[string]*Lineage) []string {
	var roots []string
	for name, entry := range graph {
		if len(entry.Parents) == 0 {
			roots = append(roots, name)
		}
	}
	sort.Strings(roots)
	return roots
}

type errInvalid string

func (e errInvalid) Error() string { return string(e) }

package chainledger

import (
	"reflect"
	"slices"
	"strings"
	"testing"
)

// buildCutoffRewireGraph builds the lineage shared by the same-name
// re-registration cutoff regressions:
//
//	source -> a ---------> report -> view
//	  |                    ^
//	  v                    |
//	  b -> mid ------------+
//	       |
//	       +-> tail
//
// source derives a and b; b derives mid; mid has the additional downstream
// tail; report depends on a and mid together; view depends on report.
func buildCutoffRewireGraph(t *testing.T) map[string]*Lineage {
	t.Helper()
	return buildRegisteredGraph(t, [][]string{
		{"source"},
		{"a", "source"},
		{"b", "source"},
		{"mid", "b"},
		{"tail", "mid"},
		{"report", "a", "mid"},
		{"view", "report"},
	})
}

// Regression for the cutoff query after a same-name Register replaces the
// dataset's direct upstreams wholesale. With a as the cutoff, report initially
// survives around it through b and mid. Re-registering report with direct
// upstreams a and tail severs the mid -> report edge while keeping a -> report
// and report -> view. The cutoff query must then be recomputed over the current
// lineage: report and view stay reachable but only via b -> mid -> tail, at
// distances 4 and 5, and the dissolved mid -> report relationship must not
// survive in any explanation. The unrestricted query still reaches report
// directly through a at distance 2; that shorter route must never be offered
// as the cutoff query's explanation.
func TestImpactsWithCutoffsReregisterReroutesViaOtherBranch(t *testing.T) {
	graph := buildCutoffRewireGraph(t)
	assertConsistent(t, graph)

	// Baseline unrestricted query: report is distance 2 through a.
	full := mustImpacts(t, graph, "source")
	assertImpactOnce(t, full, "report", 2, []string{"source", "a", "report"})
	assertImpactOnce(t, full, "view", 3, []string{"source", "a", "report", "view"})

	// Cutoff a before any re-registration: a stays in the result at distance 1,
	// but report must detour through b and mid.
	wantInitial := []Impact{
		{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
		{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
		{Dataset: "mid", Distance: 2, Path: []string{"source", "b", "mid"}},
		{Dataset: "report", Distance: 3, Path: []string{"source", "b", "mid", "report"}},
		{Dataset: "tail", Distance: 3, Path: []string{"source", "b", "mid", "tail"}},
		{Dataset: "view", Distance: 4, Path: []string{"source", "b", "mid", "report", "view"}},
	}
	initial := mustImpactsWithCutoffs(t, graph, "source", "a")
	if !reflect.DeepEqual(initial, wantInitial) {
		t.Fatalf("initial cutoff query = %v, want %v", initial, wantInitial)
	}
	// The cutoff itself is present; change simply must not travel past it.
	assertImpactOnce(t, initial, "a", 1, []string{"source", "a"})
	assertImpactOnce(t, initial, "report", 3, []string{"source", "b", "mid", "report"})
	assertImpactOnce(t, initial, "view", 4, []string{"source", "b", "mid", "report", "view"})
	initialSnapshot := copyImpacts(initial)

	// Same-name registration: replace report's direct upstreams as a whole with
	// a and tail. report keeps its own downstream view; the other branch's
	// internal b -> mid -> tail relationships are untouched; mid loses the
	// reverse edge to report and tail gains it, appended after its list.
	mustRegister(t, graph, "report", "a", "tail")
	assertConsistent(t, graph)
	assertEntry(t, graph, "report", []string{"a", "tail"}, []string{"view"})
	assertEntry(t, graph, "a", []string{"source"}, []string{"report"})
	assertEntry(t, graph, "mid", []string{"b"}, []string{"tail"})
	assertEntry(t, graph, "tail", []string{"mid"}, []string{"report"})
	assertEntry(t, graph, "b", []string{"source"}, []string{"mid"})
	assertEntry(t, graph, "view", []string{"report"}, nil)

	// The cutoff result after the replacement: report and view survive by
	// walking all the way around through tail, one edge farther each. The path
	// must not contain the dissolved mid -> report direct relationship.
	wantRerouted := []Impact{
		{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
		{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
		{Dataset: "mid", Distance: 2, Path: []string{"source", "b", "mid"}},
		{Dataset: "tail", Distance: 3, Path: []string{"source", "b", "mid", "tail"}},
		{Dataset: "report", Distance: 4, Path: []string{"source", "b", "mid", "tail", "report"}},
		{Dataset: "view", Distance: 5, Path: []string{"source", "b", "mid", "tail", "report", "view"}},
	}
	// Both library entry-point shapes (variadic and explicit cutoff slice) stay
	// compatible and agree.
	rerouted := mustImpactsWithCutoffs(t, graph, "source", "a")
	reroutedSlice, err := ImpactsWithCutoffs(graph, "source", []string{"a"})
	if err != nil {
		t.Fatalf("ImpactsWithCutoffs with explicit slice: %v", err)
	}
	if !reflect.DeepEqual(rerouted, reroutedSlice) {
		t.Fatalf("entry-point forms disagree: variadic=%v slice=%v", rerouted, reroutedSlice)
	}
	if !reflect.DeepEqual(rerouted, wantRerouted) {
		t.Fatalf("cutoff query after replacement = %v, want %v", rerouted, wantRerouted)
	}
	for _, im := range rerouted {
		if im.Path[0] != "source" || im.Path[len(im.Path)-1] != im.Dataset || len(im.Path) != im.Distance+1 {
			t.Fatalf("malformed record after replacement: %v", im)
		}
		if im.Dataset == "report" && slices.Contains(im.Path[:len(im.Path)-1], "a") {
			t.Fatalf("report explanation traverses cutoff a: %v", im.Path)
		}
	}
	assertImpactOnce(t, rerouted, "report", 4, []string{"source", "b", "mid", "tail", "report"})
	assertImpactOnce(t, rerouted, "view", 5, []string{"source", "b", "mid", "tail", "report", "view"})

	// The unrestricted query still takes the short route through a. Its shorter
	// distances and paths belong to the unrestricted query alone.
	wantFull := []Impact{
		{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
		{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
		{Dataset: "mid", Distance: 2, Path: []string{"source", "b", "mid"}},
		{Dataset: "report", Distance: 2, Path: []string{"source", "a", "report"}},
		{Dataset: "tail", Distance: 3, Path: []string{"source", "b", "mid", "tail"}},
		{Dataset: "view", Distance: 3, Path: []string{"source", "a", "report", "view"}},
	}
	afterFull := mustImpacts(t, graph, "source")
	if !reflect.DeepEqual(afterFull, wantFull) {
		t.Fatalf("unrestricted query after replacement = %v, want %v", afterFull, wantFull)
	}
	assertImpactOnce(t, afterFull, "report", 2, []string{"source", "a", "report"})
	// A nil cutoff list remains exactly the unrestricted query.
	if got, err := ImpactsWithCutoffs(graph, "source", nil); err != nil || !reflect.DeepEqual(got, afterFull) {
		t.Fatalf("nil cutoffs = %v, %v; want %v", got, err, afterFull)
	}

	// The result returned before the replacement keeps the distances and paths
	// it had at the time: queries return copies and the re-registration cannot
	// rewrite history.
	if !reflect.DeepEqual(initial, initialSnapshot) {
		t.Fatalf("earlier cutoff result changed after replacement: got %v, snapshot %v",
			initial, initialSnapshot)
	}
}

// Regression for the case where the replacement removes every bypass: after
// report is re-registered with a as its only direct upstream, a is the sole
// gateway from source to report and view. Cutting a must then drop report and
// view from the cutoff result together, while a and the still-reachable other
// branch (b, mid, tail) remain. Report and view are registered datasets, not
// missing ones: the query succeeds and must never surface a not-found error.
// The unrestricted query continues to find both through a, each exactly once.
func TestImpactsWithCutoffsReregisterOnlyCutoffUpstreamDropsSubtree(t *testing.T) {
	graph := buildCutoffRewireGraph(t)

	// Replace report's direct upstreams with a alone. mid drops its reverse
	// edge to report; tail never carried one; report keeps view.
	mustRegister(t, graph, "report", "a")
	assertConsistent(t, graph)
	assertEntry(t, graph, "report", []string{"a"}, []string{"view"})
	assertEntry(t, graph, "a", []string{"source"}, []string{"report"})
	assertEntry(t, graph, "mid", []string{"b"}, []string{"tail"})
	assertEntry(t, graph, "tail", []string{"mid"}, nil)
	assertEntry(t, graph, "view", []string{"report"}, nil)
	before := snapshot(graph)

	impacts, err := ImpactsWithCutoffs(graph, "source", []string{"a"})
	if err != nil {
		t.Fatalf("cutoff query with no remaining bypass must succeed, got %v", err)
	}
	want := []Impact{
		{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
		{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
		{Dataset: "mid", Distance: 2, Path: []string{"source", "b", "mid"}},
		{Dataset: "tail", Distance: 3, Path: []string{"source", "b", "mid", "tail"}},
	}
	if !reflect.DeepEqual(impacts, want) {
		t.Fatalf("cutoff query = %v, want %v (report and view must be gone)", impacts, want)
	}
	names := impactNames(impacts)
	for _, gone := range []string{"report", "view"} {
		if slices.Contains(names, gone) {
			t.Fatalf("%s lies only past cutoff a and must be gone, got %v", gone, names)
		}
	}
	// Every surviving dataset is listed exactly once and in the standard order.
	seen := map[string]int{}
	for _, im := range impacts {
		seen[im.Dataset]++
	}
	for name, n := range seen {
		if n != 1 {
			t.Fatalf("dataset %s listed %d times in %v", name, n, names)
		}
	}

	// report and view are still registered and directly queryable: the empty
	// scope past the cutoff is not a dataset-not-registered condition.
	fromReport := mustImpacts(t, graph, "report")
	assertImpactOnce(t, fromReport, "view", 1, []string{"report", "view"})

	// The unrestricted query still reaches report and view through a.
	full := mustImpacts(t, graph, "source")
	assertImpactOnce(t, full, "report", 2, []string{"source", "a", "report"})
	assertImpactOnce(t, full, "view", 3, []string{"source", "a", "report", "view"})
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("queries changed graph: before=%v after=%v", before, snapshot(graph))
	}
}

// Regression for a rejected same-name replacement: under the initial lineage,
// giving report the upstreams tail and view would close a cycle, because view
// is already report's downstream. The error must name view as the dataset that
// closes the loop, and the request must not take effect partially — the old
// upstreams and downstream, list ordering, unrestricted query results and the
// cutoff query results all stay exactly as they were. Queries stay read-only,
// and results already returned before the rejected replacement keep their
// original distances and paths.
func TestImpactsWithCutoffsReregisterCycleRejectedLeavesLineageAndQuery(t *testing.T) {
	graph := buildCutoffRewireGraph(t)
	assertConsistent(t, graph)

	// Capture the graph and both query shapes before the failed replacement.
	before := snapshot(graph)
	cutoffBefore := mustImpactsWithCutoffs(t, graph, "source", "a")
	cutoffSnapshot := copyImpacts(cutoffBefore)
	fullBefore := mustImpacts(t, graph, "source")
	fullSnapshot := copyImpacts(fullBefore)

	wantCutoff := []Impact{
		{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
		{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
		{Dataset: "mid", Distance: 2, Path: []string{"source", "b", "mid"}},
		{Dataset: "report", Distance: 3, Path: []string{"source", "b", "mid", "report"}},
		{Dataset: "tail", Distance: 3, Path: []string{"source", "b", "mid", "tail"}},
		{Dataset: "view", Distance: 4, Path: []string{"source", "b", "mid", "report", "view"}},
	}
	if !reflect.DeepEqual(cutoffBefore, wantCutoff) {
		t.Fatalf("baseline cutoff query = %v, want %v", cutoffBefore, wantCutoff)
	}

	// tail is a benign upstream; view is report's own downstream, so the edge
	// report -> view closes report -> view -> report. The error must name view.
	err := Register(graph, Dataset{Name: "report"}, []string{"tail", "view"})
	if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "view") {
		t.Fatalf("want cycle error naming view, got %v", err)
	}

	// The same cyclic candidate listed first must be rejected with the same
	// named error regardless of input order.
	err = Register(graph, Dataset{Name: "report"}, []string{"view", "tail"})
	if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "view") {
		t.Fatalf("reversed order: want cycle error naming view, got %v", err)
	}

	// Nothing was applied, partially or otherwise: nodes, edges and stored list
	// order are byte-for-byte the pre-request graph.
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("rejected replacement changed graph: before=%v after=%v", before, snapshot(graph))
	}
	assertEntry(t, graph, "report", []string{"a", "mid"}, []string{"view"})
	assertEntry(t, graph, "mid", []string{"b"}, []string{"tail", "report"})
	assertEntry(t, graph, "tail", []string{"mid"}, nil)
	assertEntry(t, graph, "a", []string{"source"}, []string{"report"})
	assertEntry(t, graph, "view", []string{"report"}, nil)
	assertConsistent(t, graph)

	// Both query shapes answer exactly as before the rejected replacement.
	cutoffAfter := mustImpactsWithCutoffs(t, graph, "source", "a")
	if !reflect.DeepEqual(cutoffAfter, wantCutoff) {
		t.Fatalf("cutoff query after rejection = %v, want %v", cutoffAfter, wantCutoff)
	}
	assertImpactOnce(t, cutoffAfter, "report", 3, []string{"source", "b", "mid", "report"})
	assertImpactOnce(t, cutoffAfter, "view", 4, []string{"source", "b", "mid", "report", "view"})
	fullAfter := mustImpacts(t, graph, "source")
	if !reflect.DeepEqual(fullAfter, fullSnapshot) {
		t.Fatalf("unrestricted query after rejection = %v, want %v", fullAfter, fullSnapshot)
	}

	// The pre-rejection results themselves retained the distances and paths
	// they were returned with, and the queries left no trace in the graph.
	if !reflect.DeepEqual(cutoffBefore, cutoffSnapshot) {
		t.Fatalf("earlier cutoff result changed: got %v, snapshot %v", cutoffBefore, cutoffSnapshot)
	}
	if !reflect.DeepEqual(fullBefore, fullSnapshot) {
		t.Fatalf("earlier full result changed: got %v, snapshot %v", fullBefore, fullSnapshot)
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("queries changed graph: before=%v after=%v", before, snapshot(graph))
	}
}

package chainledger

import (
	"reflect"
	"slices"
	"strings"
	"testing"
)

func mustUnregister(t *testing.T, graph map[string]*Lineage, name string) {
	t.Helper()
	if err := Unregister(graph, name); err != nil {
		t.Fatalf("Unregister(%s): %v", name, err)
	}
}

// The worked example from the spec: raw derives detail; detail derives report
// and view. Removing the leaf report deletes its registration, removes it from
// detail's downstream list while keeping view's slot and dependencies, and
// leaves the remaining lineage queryable exactly as the surviving edges
// describe.
func TestUnregisterSpecExample(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "raw")
	mustRegister(t, graph, "detail", "raw")
	mustRegister(t, graph, "report", "detail")
	mustRegister(t, graph, "view", "detail")
	// report also depends on a second source with its own other downstream.
	mustRegister(t, graph, "extra")
	mustRegister(t, graph, "otherchild", "extra")
	mustRegister(t, graph, "report", "detail", "extra")
	assertConsistent(t, graph)
	assertEntry(t, graph, "report", []string{"detail", "extra"}, nil)
	assertEntry(t, graph, "detail", []string{"raw"}, []string{"report", "view"})
	assertEntry(t, graph, "extra", nil, []string{"otherchild", "report"})

	before := snapshot(graph)
	mustUnregister(t, graph, "report")

	// The registration is gone from the map; no empty node remains.
	if _, ok := graph["report"]; ok {
		t.Fatal("report registration still present after Unregister")
	}
	if got, want := len(graph), 5; got != want {
		t.Fatalf("dataset count = %d, want %d; graph=%v", got, want, graph)
	}

	// detail loses exactly report from its children, view keeps its position.
	assertEntry(t, graph, "detail", []string{"raw"}, []string{"view"})
	// The second source loses the reverse reference to report but keeps its
	// own other downstream, in place.
	assertEntry(t, graph, "extra", nil, []string{"otherchild"})
	// view's position and dependencies are retained.
	assertEntry(t, graph, "view", []string{"detail"}, nil)
	assertEntry(t, graph, "raw", nil, []string{"detail"})
	assertEntry(t, graph, "otherchild", []string{"extra"}, nil)
	assertConsistent(t, graph)

	// No list of a node not directly connected to report gained or lost
	// anything: raw's children match the pre-call snapshot, and view's own
	// upstream list is unchanged.
	if !slices.Equal(graph["raw"].Children, before.children["raw"]) {
		t.Errorf("raw children changed: got %v, want %v", graph["raw"].Children, before.children["raw"])
	}
	if got, want := graph["view"].Parents, []string{"detail"}; !slices.Equal(got, want) {
		t.Errorf("view parents = %v, want %v", got, want)
	}

	// From raw the impact scope still reaches detail and view, never report.
	impacts := mustImpacts(t, graph, "raw")
	if got, want := impactNames(impacts), []string{"detail", "view"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Impacts(raw) = %v, want %v", got, want)
	}
	assertImpact(t, impacts, "detail", 1, []string{"raw", "detail"})
	assertImpact(t, impacts, "view", 2, []string{"raw", "detail", "view"})

	// From view the provenance trace still reaches detail and raw, with the
	// same shortest distances and explanation paths as before.
	upstreams := mustUpstreams(t, graph, "view")
	if got, want := upstreamNames(upstreams), []string{"detail", "raw"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Upstreams(view) = %v, want %v", got, want)
	}
	assertUpstream(t, upstreams, "detail", 1, []string{"detail", "view"})
	assertUpstream(t, upstreams, "raw", 2, []string{"raw", "detail", "view"})

	// The removed name is treated as unregistered by both lineage queries.
	if _, err := Impacts(graph, "report"); err == nil || !strings.Contains(err.Error(), "report") {
		t.Fatalf("Impacts(report) after removal: want not-found error naming report, got %v", err)
	}
	if _, err := Upstreams(graph, "report"); err == nil || !strings.Contains(err.Error(), "report") {
		t.Fatalf("Upstreams(report) after removal: want not-found error naming report, got %v", err)
	}

	// Removing it again reports it as unregistered and changes nothing.
	again := snapshot(graph)
	if err := Unregister(graph, "report"); err == nil || !strings.Contains(err.Error(), "report") {
		t.Fatalf("second Unregister(report): want not-found error naming report, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), again) {
		t.Fatalf("second removal attempt changed graph: before=%v after=%v", again, snapshot(graph))
	}
}

// A leaf with several direct upstreams is removed from every one of their
// downstream lists; each remaining list keeps its relative order, and
// upstreams not connected to the leaf are byte-for-byte untouched.
func TestUnregisterMultiParentLeafCleansAllReverseEdges(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "p1")
	mustRegister(t, graph, "p2")
	mustRegister(t, graph, "p3")
	mustRegister(t, graph, "a", "p1")
	mustRegister(t, graph, "leaf", "p1", "p2") // leaf between two children in p1's list
	mustRegister(t, graph, "b", "p1")
	mustRegister(t, graph, "c", "p2")
	mustRegister(t, graph, "unrelated", "p3")
	assertConsistent(t, graph)

	mustUnregister(t, graph, "leaf")

	if _, ok := graph["leaf"]; ok {
		t.Fatal("leaf still present after Unregister")
	}
	assertEntry(t, graph, "p1", nil, []string{"a", "b"})
	assertEntry(t, graph, "p2", nil, []string{"c"})
	assertEntry(t, graph, "p3", nil, []string{"unrelated"})
	assertEntry(t, graph, "a", []string{"p1"}, nil)
	assertEntry(t, graph, "b", []string{"p1"}, nil)
	assertEntry(t, graph, "c", []string{"p2"}, nil)
	assertEntry(t, graph, "unrelated", []string{"p3"}, nil)
	assertConsistent(t, graph)
}

// Relative order inside each affected list survives when the removed name sits
// at the start, middle or end, and unaffected lists stay exactly as they were.
func TestUnregisterPreservesListOrder(t *testing.T) {
	build := func() map[string]*Lineage {
		graph := map[string]*Lineage{}
		mustRegister(t, graph, "p")
		mustRegister(t, graph, "x")
		mustRegister(t, graph, "first", "p", "x")
		mustRegister(t, graph, "gone", "p", "x")
		mustRegister(t, graph, "second", "p")
		mustRegister(t, graph, "third", "p")
		return graph
	}

	positions := []struct {
		name  string
		child string
	}{
		{"first child", "first"},
		{"middle child", "gone"},
		{"last child", "third"},
	}
	for _, pos := range positions {
		graph := build()
		before := snapshot(graph)
		mustUnregister(t, graph, pos.child)

		var wantP []string
		for _, c := range before.children["p"] {
			if c != pos.child {
				wantP = append(wantP, c)
			}
		}
		assertEntry(t, graph, "p", nil, wantP)

		var wantX []string
		for _, c := range before.children["x"] {
			if c != pos.child {
				wantX = append(wantX, c)
			}
		}
		assertEntry(t, graph, "x", nil, wantX)

		// Every surviving node's lists match the pre-call lists except for the
		// removed name's deletion from its direct upstreams.
		for name, entry := range graph {
			wantParents := before.parents[name]
			if !slices.Equal(entry.Parents, wantParents) {
				t.Errorf("%s parents = %v, want %v", name, entry.Parents, wantParents)
			}
			wantChildren := before.children[name]
			if name == "p" {
				wantChildren = wantP
			}
			if name == "x" {
				wantChildren = wantX
			}
			if !slices.Equal(entry.Children, wantChildren) {
				t.Errorf("%s children = %v, want %v", name, entry.Children, wantChildren)
			}
		}
		assertConsistent(t, graph)
	}
}

// A standalone dataset with neither upstreams nor downstreams is removed
// successfully.
func TestUnregisterIsolatedDataset(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "lonely")
	mustRegister(t, graph, "keep")
	mustRegister(t, graph, "child", "keep")

	mustUnregister(t, graph, "lonely")
	if _, ok := graph["lonely"]; ok {
		t.Fatal("lonely still present after Unregister")
	}
	if got, want := len(graph), 2; got != want {
		t.Fatalf("dataset count = %d, want %d", got, want)
	}
	assertEntry(t, graph, "keep", nil, []string{"child"})
	assertEntry(t, graph, "child", []string{"keep"}, nil)
	assertConsistent(t, graph)

	// The last remaining datasets can be peeled off leaf first, then the root.
	mustUnregister(t, graph, "child")
	mustUnregister(t, graph, "keep")
	if len(graph) != 0 {
		t.Fatalf("graph = %v, want empty graph", graph)
	}
}

// A dataset with a direct downstream cannot be removed, no matter how many
// upstreams it has; the error names it and says it still has downstreams, and
// the refusal is atomic.
func TestUnregisterRejectedWhileDownstreamsRemain(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "raw")
	mustRegister(t, graph, "src2")
	mustRegister(t, graph, "detail", "raw", "src2")
	mustRegister(t, graph, "report", "detail")
	mustRegister(t, graph, "view", "report")
	before := snapshot(graph)

	err := Unregister(graph, "detail")
	if err == nil {
		t.Fatal("expected rejection for dataset with downstream, got nil")
	}
	if !strings.Contains(err.Error(), "detail") {
		t.Errorf("error %q should name the dataset detail", err.Error())
	}
	if !strings.Contains(err.Error(), "downstream") {
		t.Errorf("error %q should state that direct downstreams remain", err.Error())
	}

	// No partial modification: node present, all edges and list orders intact.
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("rejected unregister changed graph: before=%v after=%v", before, snapshot(graph))
	}
	assertEntry(t, graph, "detail", []string{"raw", "src2"}, []string{"report"})
	assertEntry(t, graph, "raw", nil, []string{"detail"})
	assertEntry(t, graph, "src2", nil, []string{"detail"})
	assertEntry(t, graph, "report", []string{"detail"}, []string{"view"})
	assertEntry(t, graph, "view", []string{"report"}, nil)
	assertConsistent(t, graph)

	// A root that still feeds a dataset is refused the same way.
	err = Unregister(graph, "raw")
	if err == nil || !strings.Contains(err.Error(), "raw") || !strings.Contains(err.Error(), "downstream") {
		t.Fatalf("root with child: want error naming raw and its downstream, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("second rejection changed graph: before=%v after=%v", before, snapshot(graph))
	}

	// After the child chain is gone, the refusals become legal removals.
	mustUnregister(t, graph, "view")
	mustUnregister(t, graph, "report")
	mustUnregister(t, graph, "detail")
	assertEntry(t, graph, "raw", nil, nil)
	assertEntry(t, graph, "src2", nil, nil)
	assertConsistent(t, graph)
}

// In a diamond, the merge node and its exclusive downstream leave together only
// after the downstream is removed; until then the merge stays and the shared
// sources' child lists are untouched by the refused request.
func TestUnregisterDiamondLeafThenMerge(t *testing.T) {
	graph := buildRegisteredGraph(t, [][]string{
		{"raw"},
		{"a", "raw"},
		{"b", "raw"},
		{"merge", "a", "b"},
		{"down", "merge"},
	})
	before := snapshot(graph)

	// merge has a direct downstream: refused, nothing changes.
	if err := Unregister(graph, "merge"); err == nil ||
		!strings.Contains(err.Error(), "merge") || !strings.Contains(err.Error(), "downstream") {
		t.Fatalf("want downstream error naming merge, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("rejected removal changed graph: before=%v after=%v", before, snapshot(graph))
	}

	mustUnregister(t, graph, "down")
	assertEntry(t, graph, "merge", []string{"a", "b"}, nil)
	assertConsistent(t, graph)

	mustUnregister(t, graph, "merge")
	if _, ok := graph["merge"]; ok {
		t.Fatal("merge still present after Unregister")
	}
	// Both parents lose merge; raw keeps both branches in their order.
	assertEntry(t, graph, "a", []string{"raw"}, nil)
	assertEntry(t, graph, "b", []string{"raw"}, nil)
	assertEntry(t, graph, "raw", nil, []string{"a", "b"})
	assertConsistent(t, graph)
}

// All error cases name the problem correctly and never touch the graph.
func TestUnregisterErrors(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "a")
	mustRegister(t, graph, "b", "a")
	before := snapshot(graph)

	// Empty name: missing name.
	if err := Unregister(graph, ""); err == nil || !strings.Contains(err.Error(), "name is required") {
		t.Fatalf("empty name: want required-name error, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatal("empty-name rejection changed the graph")
	}

	// Non-empty unregistered name against a populated graph.
	if err := Unregister(graph, "ghost"); err == nil || !strings.Contains(err.Error(), "ghost") {
		t.Fatalf("unknown name: want error naming ghost, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatal("unknown-name rejection changed the graph")
	}

	// An initialized-but-empty graph treats any non-empty name as unregistered.
	if err := Unregister(map[string]*Lineage{}, "ghost"); err == nil ||
		!strings.Contains(err.Error(), "ghost") {
		t.Fatalf("empty graph: want error naming ghost, got %v", err)
	}

	// A nil graph behaves the same.
	if err := Unregister(nil, "ghost"); err == nil || !strings.Contains(err.Error(), "ghost") {
		t.Fatalf("nil graph: want error naming ghost, got %v", err)
	}
	if err := Unregister(nil, ""); err == nil || !strings.Contains(err.Error(), "name is required") {
		t.Fatalf("nil graph empty name: want required-name error, got %v", err)
	}

	assertEntry(t, graph, "a", nil, []string{"b"})
	assertEntry(t, graph, "b", []string{"a"}, nil)
	assertConsistent(t, graph)
}

// Names match by exact registered value, case-sensitive: a differently cased
// request is unregistered-or-not independently, and removing one case variant
// leaves the other in place.
func TestUnregisterExactNameMatch(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "raw")
	mustRegister(t, graph, "report", "raw")
	mustRegister(t, graph, "Report", "raw")
	assertConsistent(t, graph)

	// "Report" with the wrong case is not registered.
	if err := Unregister(graph, "RePoRt"); err == nil || !strings.Contains(err.Error(), "RePoRt") {
		t.Fatalf("case-insensitive match: want not-found error naming RePoRt, got %v", err)
	}

	// Removing the uppercase variant leaves the lowercase report and raw.
	mustUnregister(t, graph, "Report")
	if _, ok := graph["Report"]; ok {
		t.Fatal("Report still present after Unregister")
	}
	assertEntry(t, graph, "report", []string{"raw"}, nil)
	assertEntry(t, graph, "raw", nil, []string{"report"})
	assertConsistent(t, graph)

	mustUnregister(t, graph, "report")
	if _, ok := graph["report"]; ok {
		t.Fatal("report still present after Unregister")
	}
	assertEntry(t, graph, "raw", nil, nil)
}

// Regression for the real migration case: the downstreams stay registered but
// move to another source by same-name re-registration, after which the dataset
// they used to depend on becomes removable. Eligibility must always follow the
// CURRENT direct downstreams: a dataset that once had downstreams must not stay
// unremovable forever, but moving just one of two downstreams must not make it
// removable early either.
//
// detail depends on two sources srca and srcb and has two direct downstreams
// summary and view; summary derives report; each source also feeds an unrelated
// branch (sideA, sideB); alt is a registered replacement source. The sequence:
//
//  1. Unregister(detail) fails while both direct downstreams exist; nothing
//     moves.
//  2. summary's direct upstreams are replaced wholesale by alt. summary and
//     report survive; view still depends on detail.
//  3. Unregister(detail) must STILL be refused, and that refusal must neither
//     roll back the successful source replacement nor clean up detail's edges
//     to srca and srcb.
//  4. view moves to alt the same way; detail now has no direct downstream,
//     though it still has two upstreams.
//  5. Unregister(detail) succeeds: only its registration disappears; both
//     sources lose it from their child lists keeping the remaining order;
//     summary, view, report, alt and the unrelated branches are untouched, and
//     the newly built alt -> summary -> report / alt -> view lineage queries
//     exactly like that.
func TestUnregisterEligibilityFollowsCurrentDirectDownstreams(t *testing.T) {
	graph := map[string]*Lineage{}
	// Registration order is chosen so the stored child lists have meaningful
	// positions to preserve later: srca gains sideA before detail; srcb gains
	// detail before sideB; detail gains summary before view.
	mustRegister(t, graph, "srca")
	mustRegister(t, graph, "srcb")
	mustRegister(t, graph, "alt")
	mustRegister(t, graph, "sideA", "srca")
	mustRegister(t, graph, "detail", "srca", "srcb")
	mustRegister(t, graph, "sideB", "srcb")
	mustRegister(t, graph, "summary", "detail")
	mustRegister(t, graph, "report", "summary")
	mustRegister(t, graph, "view", "detail")
	assertConsistent(t, graph)

	assertEntry(t, graph, "srca", nil, []string{"sideA", "detail"})
	assertEntry(t, graph, "srcb", nil, []string{"detail", "sideB"})
	assertEntry(t, graph, "alt", nil, nil)
	assertEntry(t, graph, "detail", []string{"srca", "srcb"}, []string{"summary", "view"})
	assertEntry(t, graph, "summary", []string{"detail"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"summary"}, nil)
	assertEntry(t, graph, "view", []string{"detail"}, nil)
	assertEntry(t, graph, "sideA", []string{"srca"}, nil)
	assertEntry(t, graph, "sideB", []string{"srcb"}, nil)

	// Baseline queries over the starting lineage: detail affects both direct
	// downstreams at distance 1 and report through summary at distance 2;
	// report's provenance runs back through summary and detail to both sources.
	detailImpacts := mustImpacts(t, graph, "detail")
	if got, want := impactNames(detailImpacts), []string{"summary", "view", "report"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("initial Impacts(detail) = %v, want %v", got, want)
	}
	assertImpact(t, detailImpacts, "summary", 1, []string{"detail", "summary"})
	assertImpact(t, detailImpacts, "view", 1, []string{"detail", "view"})
	assertImpact(t, detailImpacts, "report", 2, []string{"detail", "summary", "report"})
	reportUpstreams := mustUpstreams(t, graph, "report")
	if got, want := upstreamNames(reportUpstreams), []string{"summary", "detail", "srca", "srcb"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("initial Upstreams(report) = %v, want %v", got, want)
	}
	assertUpstream(t, reportUpstreams, "summary", 1, []string{"summary", "report"})
	assertUpstream(t, reportUpstreams, "detail", 2, []string{"detail", "summary", "report"})
	assertUpstream(t, reportUpstreams, "srca", 3, []string{"srca", "detail", "summary", "report"})
	assertUpstream(t, reportUpstreams, "srcb", 3, []string{"srcb", "detail", "summary", "report"})
	// alt is registered but not yet part of report's provenance.
	if slices.Contains(upstreamNames(reportUpstreams), "alt") {
		t.Fatalf("alt must not be an upstream of report before the move: %v", reportUpstreams)
	}

	// Phase 1: detail still has summary and view as direct downstreams.
	original := snapshot(graph)
	err := Unregister(graph, "detail")
	if err == nil {
		t.Fatal("initial Unregister(detail): expected refusal, got nil")
	}
	if !strings.Contains(err.Error(), "detail") || !strings.Contains(err.Error(), "downstream") {
		t.Fatalf("initial Unregister(detail): want error naming detail and its remaining downstream, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), original) {
		t.Fatalf("initial refusal changed graph: before=%v after=%v", original, snapshot(graph))
	}
	assertConsistent(t, graph)

	// Phase 2: move summary to alt by replacing its whole direct-upstream list.
	// summary keeps its own downstream report; detail loses summary from its
	// child list but keeps view in place, and detail's edges to srca/srcb are
	// not part of this request.
	mustRegister(t, graph, "summary", "alt")
	assertConsistent(t, graph)
	assertEntry(t, graph, "summary", []string{"alt"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"summary"}, nil)
	assertEntry(t, graph, "alt", nil, []string{"summary"})
	assertEntry(t, graph, "detail", []string{"srca", "srcb"}, []string{"view"})
	assertEntry(t, graph, "view", []string{"detail"}, nil)
	assertEntry(t, graph, "srca", nil, []string{"sideA", "detail"})
	assertEntry(t, graph, "srcb", nil, []string{"detail", "sideB"})
	assertEntry(t, graph, "sideA", []string{"srca"}, nil)
	assertEntry(t, graph, "sideB", []string{"srcb"}, nil)

	// With summary gone, detail affects only view; the summary/report branch is
	// no longer reachable from detail.
	detailImpacts = mustImpacts(t, graph, "detail")
	if got, want := impactNames(detailImpacts), []string{"view"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("after moving summary, Impacts(detail) = %v, want %v", got, want)
	}
	assertImpact(t, detailImpacts, "view", 1, []string{"detail", "view"})
	// alt now feeds summary and report along the newly built edges.
	altImpacts := mustImpacts(t, graph, "alt")
	if got, want := impactNames(altImpacts), []string{"summary", "report"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("after moving summary, Impacts(alt) = %v, want %v", got, want)
	}
	assertImpact(t, altImpacts, "summary", 1, []string{"alt", "summary"})
	assertImpact(t, altImpacts, "report", 2, []string{"alt", "summary", "report"})
	// report's provenance now runs through summary back to alt, never detail or
	// the two original sources.
	reportUpstreams = mustUpstreams(t, graph, "report")
	if got, want := upstreamNames(reportUpstreams), []string{"summary", "alt"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("after moving summary, Upstreams(report) = %v, want %v", got, want)
	}
	assertUpstream(t, reportUpstreams, "summary", 1, []string{"summary", "report"})
	assertUpstream(t, reportUpstreams, "alt", 2, []string{"alt", "summary", "report"})
	viewUpstreams := mustUpstreams(t, graph, "view")
	if got, want := upstreamNames(viewUpstreams), []string{"detail", "srca", "srcb"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("view must still trace through detail: got %v, want %v", got, want)
	}

	// Phase 3: view still depends on detail, so moving just one downstream must
	// not make detail removable.
	afterSummaryMove := snapshot(graph)
	err = Unregister(graph, "detail")
	if err == nil {
		t.Fatal("Unregister(detail) with view still downstream: expected refusal, got nil")
	}
	if !strings.Contains(err.Error(), "detail") || !strings.Contains(err.Error(), "downstream") {
		t.Fatalf("second Unregister(detail): want error naming detail and its remaining downstream, got %v", err)
	}
	// The refusal changes nothing: in particular it does not undo summary's
	// successful move to alt, and does not detach detail from srca/srcb.
	if !reflect.DeepEqual(snapshot(graph), afterSummaryMove) {
		t.Fatalf("second refusal changed graph: before=%v after=%v", afterSummaryMove, snapshot(graph))
	}
	assertEntry(t, graph, "summary", []string{"alt"}, []string{"report"})
	assertEntry(t, graph, "alt", nil, []string{"summary"})
	assertEntry(t, graph, "detail", []string{"srca", "srcb"}, []string{"view"})
	assertEntry(t, graph, "view", []string{"detail"}, nil)
	assertEntry(t, graph, "srca", nil, []string{"sideA", "detail"})
	assertEntry(t, graph, "srcb", nil, []string{"detail", "sideB"})
	assertConsistent(t, graph)

	// The queryable lineage after the refusal is still the post-move lineage.
	if got := mustImpacts(t, graph, "detail"); !reflect.DeepEqual(got, detailImpacts) {
		t.Fatalf("Impacts(detail) changed after the refusal: got %v, want %v", got, detailImpacts)
	}
	if got := mustUpstreams(t, graph, "report"); !reflect.DeepEqual(got, reportUpstreams) {
		t.Fatalf("Upstreams(report) changed after the refusal: got %v, want %v", got, reportUpstreams)
	}

	// Phase 4: view also replaces its direct upstream with alt. detail now has
	// no direct downstream, while still declaring two upstreams.
	mustRegister(t, graph, "view", "alt")
	assertConsistent(t, graph)
	assertEntry(t, graph, "view", []string{"alt"}, nil)
	assertEntry(t, graph, "alt", nil, []string{"summary", "view"}) // view appended after summary
	assertEntry(t, graph, "detail", []string{"srca", "srcb"}, nil)
	assertEntry(t, graph, "summary", []string{"alt"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"summary"}, nil)

	// Phase 5: detail is a leaf despite its two upstreams, so removal succeeds.
	if err := Unregister(graph, "detail"); err != nil {
		t.Fatalf("Unregister(detail) after both downstreams moved: %v", err)
	}
	if _, ok := graph["detail"]; ok {
		t.Fatal("detail registration still present after Unregister")
	}
	if got, want := len(graph), 8; got != want {
		t.Fatalf("dataset count = %d, want %d; graph=%v", got, want, graph)
	}
	// Both original sources drop detail and keep their other downstream in its
	// original position; nothing else on those branches is deleted or rewritten.
	assertEntry(t, graph, "srca", nil, []string{"sideA"})
	assertEntry(t, graph, "srcb", nil, []string{"sideB"})
	assertEntry(t, graph, "sideA", []string{"srca"}, nil)
	assertEntry(t, graph, "sideB", []string{"srcb"}, nil)
	// The moved datasets and the replacement source survive with the newly
	// built dependencies intact.
	assertEntry(t, graph, "alt", nil, []string{"summary", "view"})
	assertEntry(t, graph, "summary", []string{"alt"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"summary"}, nil)
	assertEntry(t, graph, "view", []string{"alt"}, nil)
	assertConsistent(t, graph)
	if got, want := Roots(graph), []string{"alt", "srca", "srcb"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Roots = %v, want %v", got, want)
	}

	// The original sources no longer reach the moved datasets through detail;
	// each keeps only its unrelated branch.
	if got, want := impactNames(mustImpacts(t, graph, "srca")), []string{"sideA"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Impacts(srca) after removal = %v, want %v", got, want)
	}
	if got, want := impactNames(mustImpacts(t, graph, "srcb")), []string{"sideB"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Impacts(srcb) after removal = %v, want %v", got, want)
	}
	// alt still affects all three moved datasets, ordered by distance then name:
	// summary and view at distance 1 (summary < view), report at distance 2 via
	// summary.
	altImpacts = mustImpacts(t, graph, "alt")
	if got, want := impactNames(altImpacts), []string{"summary", "view", "report"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Impacts(alt) after removal = %v, want %v", got, want)
	}
	assertImpact(t, altImpacts, "summary", 1, []string{"alt", "summary"})
	assertImpact(t, altImpacts, "view", 1, []string{"alt", "view"})
	assertImpact(t, altImpacts, "report", 2, []string{"alt", "summary", "report"})
	// summary still reaches report, and report's provenance still runs through
	// summary to alt with the existing distance and explanation rules.
	assertImpact(t, mustImpacts(t, graph, "summary"), "report", 1, []string{"summary", "report"})
	reportUpstreams = mustUpstreams(t, graph, "report")
	if got, want := upstreamNames(reportUpstreams), []string{"summary", "alt"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Upstreams(report) after removal = %v, want %v", got, want)
	}
	assertUpstream(t, reportUpstreams, "summary", 1, []string{"summary", "report"})
	assertUpstream(t, reportUpstreams, "alt", 2, []string{"alt", "summary", "report"})
	assertUpstream(t, mustUpstreams(t, graph, "view"), "alt", 1, []string{"alt", "view"})

	// The removed name is an error, not a successful empty result, in every
	// public entry point that names a dataset.
	impacts, err := Impacts(graph, "detail")
	if err == nil || !strings.Contains(err.Error(), "detail") {
		t.Fatalf("Impacts(detail) after removal: want not-found error naming detail, got %v", err)
	}
	if impacts != nil {
		t.Fatalf("Impacts(detail) after removal: want nil results, got %v", impacts)
	}
	upstreams, err := Upstreams(graph, "detail")
	if err == nil || !strings.Contains(err.Error(), "detail") {
		t.Fatalf("Upstreams(detail) after removal: want not-found error naming detail, got %v", err)
	}
	if upstreams != nil {
		t.Fatalf("Upstreams(detail) after removal: want nil results, got %v", upstreams)
	}
	if err := Unregister(graph, "detail"); err == nil || !strings.Contains(err.Error(), "detail") {
		t.Fatalf("second Unregister(detail): want not-found error naming detail, got %v", err)
	}
}

// After a successful removal, registration under the freed name starts a
// completely fresh dataset, and the rest of the lineage keeps working.
func TestUnregisterThenRegisterFresh(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "raw")
	mustRegister(t, graph, "leaf", "raw")

	mustUnregister(t, graph, "leaf")
	assertEntry(t, graph, "raw", nil, nil)

	// The freed name registers as a brand-new isolated dataset.
	mustRegister(t, graph, "leaf")
	assertEntry(t, graph, "leaf", nil, nil)
	assertEntry(t, graph, "raw", nil, nil)
	assertConsistent(t, graph)

	// And it can take part in new lineage afterwards.
	mustRegister(t, graph, "leaf", "raw")
	assertEntry(t, graph, "leaf", []string{"raw"}, nil)
	assertEntry(t, graph, "raw", nil, []string{"leaf"})
	assertConsistent(t, graph)
}

