		t.Fatalf("nil cutoffs = %v, want full Impacts %v", nilCut, full)
	}
	// An explicit empty slice behaves the same.
	if got, err := ImpactsWithCutoffs(graph, "source", []string{}); err != nil || !reflect.DeepEqual(got, full) {
